from scipy.optimize import least_squares
def simQ(p,D,kind):
    t=D['time_s']; V=D['voltage_pu']; Vs=D['voltage_setpoint_pu']; Q0=D['reactive_power_pu'][0]; V0=V[0]
    n=len(t); Qo=np.empty(n); Qo[0]=Q0
    if kind=='C1': Ka,Kb,Tq=p; Tm=1e-3
    else: Ka,Kb,Tq,Tm=p
    vf=V0; q=Q0
    for k in range(1,n):
        h=t[k]-t[k-1]
        vf+= h*(V[k-1]-vf)/Tm
        dq=(Q0+Ka*(Vs[k-1]-V0)-Kb*(vf-V0)-q)/Tq
        q+=h*dq; Qo[k]=q
    return Qo
def rq(p,names,kind):
    r=[]
    for f in names:
        D=load(f); r.append(simQ(p,D,kind)-D['reactive_power_pu'])
    return np.concatenate(r)
