def build(files,na,nb,ins,dec=5,target='reactive_power_pu'):
    X=[];Y=[]
    for f in files:
        D=load(f)
        sig={'V':D['voltage_pu'],'Vs':D['voltage_setpoint_pu'],'P':D['active_power_pu'],'th':D['bus_angle_rad'],'Q':D[target]}
        sig={k:v[::dec] for k,v in sig.items()}
        sig['th']=np.gradient(sig['th'],dec*1e-3)  # use dtheta/dt
        n=len(sig['Q'])
        for k in range(max(na,nb),n):
            row=[-sig['Q'][k-i] for i in range(1,na+1)]
            for s in ins:
                row+=[sig[s][k-i] for i in range(0,nb)]
            X.append(row); Y.append(sig['Q'][k])
    return np.array(X),np.array(Y)
