def build(na,nb):
    X=[];Y=[]
    for f in files:
        S=get(f); V=S['voltage_pu']; Vs=S['voltage_setpoint_pu']; Q=S['reactive_power_pu']
        for k in range(max(na,nb),len(Q)):
