def freerun(th,S,na,nb):
    V=S['voltage_pu']; Vs=S['voltage_setpoint_pu']; Q=S['reactive_power_pu']
    n=len(Q); out=np.empty(n); out[:max(na,nb)]=Q[:max(na,nb)]
    for k in range(max(na,nb),n):
        out[k]=sum(-th[i]*out[k-1-i] for i in range(na))+sum(th[na+i]*V[k-i] for i in range(nb))+sum(th[na+nb+i]*Vs[k-i] for i in range(nb))
    return out
