def xc(f,t0,t1,key='voltage_pu'):
    D=load(f); t=D['time_s']; m=(t>=t0)&(t<=t1)
    V=D[key][m]-np.mean(D[key][m]); Q=D['reactive_power_pu'][m]-np.mean(D['reactive_power_pu'][m])
    out=[]
    for lag_ms in [-200,-100,-50,-20,-10,0,10,20,50,100,200]:
        L=lag_ms
        if L>=0: c=np.corrcoef(V[:len(V)-L] if L>0 else V, Q[L:] if L>0 else Q)[0,1]
        else: c=np.corrcoef(V[-L:],Q[:len(Q)+L])[0,1]
        out.append((lag_ms,round(c,3)))
    # regression slope
    sl=np.polyfit(V,Q,1)[0]
    return out,round(sl,3)
