def simSS(p,S):
    # x' = A x + B [dV, dVs]; Q = Q0 + C x + D [dV,dVs]
    A=np.array([[p[0],p[1]],[p[2],p[3]]]); B=np.array([[p[4],p[5]],[p[6],p[7]]]); C=np.array([p[8],p[9]]); Dv=np.array([p[10],p[11]])
    t=S['time_s']; V=S['voltage_pu']; Vs=S['voltage_setpoint_pu']; Q0=S['reactive_power_pu'][0]; V0=V[0]; Vs0=Vs[0]
    n=len(t); Qo=np.empty(n); Qo[0]=Q0; x=np.zeros(2)
    U=np.column_stack([V-V0,Vs-Vs0])
    for k in range(1,n):
        h=t[k]-t[k-1]
        u=U[k-1]
        x=x+h*(A@x+B@u)
        Qo[k]=Q0+C@x+Dv@U[k]
    return Qo
